def count_pairs(nums, target):
    counts = {}
    for x in nums:
        c = counts.get(x)
        if c is None:
            counts[x] = 1
        else:
            counts[x] = c + 1
    total = 0
    for x, c in counts.items():
        need = target - x
        if need in counts:
            c2 = counts[need]
            if x == need:
                total += c * (c - 1) // 2
            elif x < need:
                total += c * c2
    return total


